<?php
session_start(); require_once __DIR__.'/../autenticacao.php'; require_once __DIR__.'/conexaoDB.php'; require_once __DIR__.'/../cabecalho.php'; exigirLogin('gerente'); $farmaciaId=(int)$_SESSION['farmacia_id'];
$inicio=$_GET['inicio']??date('Y-m-01'); $fim=$_GET['fim']??date('Y-m-d'); if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$inicio))$inicio=date('Y-m-01'); if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$fim))$fim=date('Y-m-d');
$cond="AND DATE(v.data_venda) BETWEEN '$inicio' AND '$fim'";
$stmt=mysqli_prepare($conexao,"SELECT COUNT(*) vendas,COALESCE(SUM(v.valor_total),0) faturamento,COALESCE(AVG(v.valor_total),0) ticket FROM vendas v WHERE v.farmacia_id=? AND v.status='concluida' $cond"); mysqli_stmt_bind_param($stmt,'i',$farmaciaId); mysqli_stmt_execute($stmt); $resumo=mysqli_fetch_assoc(mysqli_stmt_get_result($stmt));

$di = new DateTime($inicio); $df = new DateTime($fim); $dias = $di->diff($df)->days + 1;
$anteriorFim = (clone $di)->modify('-1 day')->format('Y-m-d');
$anteriorInicio = (clone $di)->modify('-'.$dias.' day')->format('Y-m-d');
$stmt=mysqli_prepare($conexao,"SELECT COALESCE(SUM(v.valor_total),0) faturamento FROM vendas v WHERE v.farmacia_id=? AND v.status='concluida' AND DATE(v.data_venda) BETWEEN ? AND ?"); mysqli_stmt_bind_param($stmt,'iss',$farmaciaId,$anteriorInicio,$anteriorFim); mysqli_stmt_execute($stmt); $fatAnterior=(float)mysqli_fetch_assoc(mysqli_stmt_get_result($stmt))['faturamento'];
$fatAtual=(float)$resumo['faturamento']; $variacao=$fatAnterior>0?(($fatAtual-$fatAnterior)/$fatAnterior)*100:null;
$stmt=mysqli_prepare($conexao,"SELECT p.nome,c.nome categoria,SUM(i.quantidade) quantidade,SUM(i.subtotal) total FROM itens_venda i INNER JOIN vendas v ON v.id=i.venda_id INNER JOIN produtos p ON p.id=i.produto_id LEFT JOIN categorias c ON c.id=p.categoria_id WHERE v.farmacia_id=? AND v.status='concluida' $cond GROUP BY p.id,p.nome,c.nome ORDER BY quantidade DESC LIMIT 20"); mysqli_stmt_bind_param($stmt,'i',$farmaciaId); mysqli_stmt_execute($stmt); $produtos=mysqli_fetch_all(mysqli_stmt_get_result($stmt),MYSQLI_ASSOC);
$stmt=mysqli_prepare($conexao,"SELECT u.nome,COUNT(v.id) vendas,COALESCE(SUM(v.valor_total),0) total FROM vendas v INNER JOIN usuarios u ON u.id=v.usuario_id WHERE v.farmacia_id=? AND v.status='concluida' $cond GROUP BY u.id,u.nome ORDER BY total DESC"); mysqli_stmt_bind_param($stmt,'i',$farmaciaId); mysqli_stmt_execute($stmt); $vendedores=mysqli_fetch_all(mysqli_stmt_get_result($stmt),MYSQLI_ASSOC);
$stmt=mysqli_prepare($conexao,"SELECT v.forma_pagamento,COUNT(*) quantidade,SUM(v.valor_total) total FROM vendas v WHERE v.farmacia_id=? AND v.status='concluida' $cond GROUP BY v.forma_pagamento ORDER BY total DESC"); mysqli_stmt_bind_param($stmt,'i',$farmaciaId); mysqli_stmt_execute($stmt); $pagamentos=mysqli_fetch_all(mysqli_stmt_get_result($stmt),MYSQLI_ASSOC);
?>
<!DOCTYPE html><html lang="pt-BR"><head><?php recursosCabeca('Relatórios'); ?><style>@media print{.no-print,.navbar,.menu-app,.offcanvas{display:none!important}body{background:#fff}}</style></head><body><?php cabecalho('FarmaCerta - Gerente','gerente','relatorios'); ?><main class="container py-4"><section class="card card-brand rounded-4 p-4 mb-4 no-print"><h2 class="h3 fw-bold">RELATÓRIOS</h2><form class="row g-3 align-items-end"><div class="col-md-4"><label class="form-label">Data inicial</label><input class="form-control" type="date" name="inicio" value="<?php echo htmlspecialchars($inicio); ?>"></div><div class="col-md-4"><label class="form-label">Data final</label><input class="form-control" type="date" name="fim" value="<?php echo htmlspecialchars($fim); ?>"></div><div class="col-md-4 d-flex gap-2"><button class="btn btn-outline-light rounded-pill">FILTRAR</button><a class="btn btn-outline-light rounded-pill" href="exportarrelatorio.php?inicio=<?php echo urlencode($inicio); ?>&fim=<?php echo urlencode($fim); ?>">CSV</a><button type="button" class="btn btn-outline-light rounded-pill" onclick="window.print()">IMPRIMIR</button></div></form></section><section class="row g-3 mb-4"><div class="col-md-4"><article class="card p-4"><small>FATURAMENTO</small><strong class="fs-3 text-primary">R$ <?php echo number_format($resumo['faturamento'],2,',','.'); ?></strong><small class="text-secondary mt-2">Período anterior: R$ <?php echo number_format($fatAnterior,2,',','.'); ?><?php if($variacao!==null){ ?> · <?php echo $variacao>=0?'+':''; ?><?php echo number_format($variacao,1,',','.'); ?>%<?php } ?></small></article></div><div class="col-md-4"><article class="card p-4"><small>VENDAS</small><strong class="fs-3"><?php echo (int)$resumo['vendas']; ?></strong></article></div><div class="col-md-4"><article class="card p-4"><small>TICKET MÉDIO</small><strong class="fs-3">R$ <?php echo number_format($resumo['ticket'],2,',','.'); ?></strong></article></div></section><section class="row g-3"><div class="col-xl-6"><article class="card p-3 h-100"><h3 class="h5 fw-bold">PRODUTOS MAIS VENDIDOS</h3><div class="table-responsive"><table class="table"><thead><tr><th>Produto</th><th>Categoria</th><th>Qtd.</th><th>Total</th></tr></thead><tbody><?php foreach($produtos as $p){ ?><tr><td><?php echo htmlspecialchars($p['nome']); ?></td><td><?php echo htmlspecialchars($p['categoria']?:'Sem categoria'); ?></td><td><?php echo (int)$p['quantidade']; ?></td><td>R$ <?php echo number_format($p['total'],2,',','.'); ?></td></tr><?php } ?></tbody></table></div></article></div><div class="col-xl-6"><article class="card p-3 h-100"><h3 class="h5 fw-bold">VENDAS POR BALCONISTA</h3><table class="table"><thead><tr><th>Balconista</th><th>Vendas</th><th>Total</th></tr></thead><tbody><?php foreach($vendedores as $v){ ?><tr><td><?php echo htmlspecialchars($v['nome']); ?></td><td><?php echo (int)$v['vendas']; ?></td><td>R$ <?php echo number_format($v['total'],2,',','.'); ?></td></tr><?php } ?></tbody></table></article></div><div class="col-12"><article class="card p-3"><h3 class="h5 fw-bold">FORMAS DE PAGAMENTO</h3><table class="table"><thead><tr><th>Forma</th><th>Vendas</th><th>Total</th></tr></thead><tbody><?php foreach($pagamentos as $p){ ?><tr><td><?php echo ucfirst(htmlspecialchars($p['forma_pagamento'])); ?></td><td><?php echo (int)$p['quantidade']; ?></td><td>R$ <?php echo number_format($p['total'],2,',','.'); ?></td></tr><?php } ?></tbody></table></article></div></section></main><?php recursosRodape(); ?></body></html>